rowObjects.data:
{{
  (() => {
    const stammdatenArray = Stammdaten.data || [];

    // Die aktuell geänderte Zeile aus Table2 holen
    const updatedRow = Table2.updatedRow || Table2.triggeredRow || {};

    // Die Zeile im Stammdaten-Array anhand von Haus und Bahn suchen
    // (Oder ein eindeutiges Merkmal wie `Ventil_Links` / `Ventil_Rechts`)
    const targetIdx = stammdatenArray.findIndex(r => 
      String(r.Haus || "").trim() === String(updatedRow.Haus || "").trim() &&
      String(r.Bahn || "").trim() === String(updatedRow.Bahn || "").trim()
    );

    if (targetIdx === -1) {
      return {};
    }

    // Google Sheets ist 1-basiert und hat 1 Header-Zeile -> Index + 2
    return {
      "rowIndex": targetIdx + 2,
      "Haus_Aktiv": updatedRow.Aktiv
    };
  })()
}}
